/// <summary>
/// CB167_PerformStockReservation.
/// This is a UI builder class for reserve event orders batch job.
/// </summary>
class METReserveEventOrdersUIBuilder  extends SysOperationAutomaticUIBuilder
{
    private DialogField eventIdDialogField;
    private METReserveEventOrdersContract eventOrderDataContract;

}

Method.Source:
/// <summary>
/// Overrides the method to add custom logic.
/// </summary>
public void postBuild()
{
    super();

    eventOrderDataContract = this.dataContractObject();
    eventIdDialogField = this.bindInfo().getDialogField(eventOrderDataContract, methodStr(METReserveEventOrdersContract, parmEventId));

    eventIdDialogField.registerOverrideMethod(methodstr(FormStringControl, lookup), methodstr(METReserveEventOrdersUIBuilder, lookupEventId), this);
}

/// <summary>
/// Constructs lookup againt event Id.
/// </summary>
/// <param name = "_control">
/// <c>FormStringControl</c>.
/// </param>
private void lookupEventId(FormStringControl _control)
{
    Query                query;
    QueryBuildDataSource qbds;
    SysTableLookup       sysTableLookup;

    query = new Query();
    qbds  = query.addDataSource(tableNum(METSalesTable));

    qbds.addRange(fieldNum(METSalesTable, EventID)).value(SysQuery::valueNotEmptyString());
    qbds.addGroupByField(fieldNum(METSalesTable, EventID));

    sysTableLookup = SysTableLookup::newParameters(tableNum(METSalesTable), _control);

    sysTableLookup.addLookupField(fieldNum(METSalesTable, EventID), true);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
